mapper.insert:

    SELECT
        'CARE'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(CAREER_NO), LENGTH('CRER' ) + 1)), 0) + 1, 6, '0')
    FROM CAREER

	INSERT INTO CAREER (
		CAREER_NO
		, RESUME_NO
		, JOB_CODE
		, START_WORK_DATE
		, RETIRE_DATE
		, TENURE
		, DEPARTMENT
		, RESPONSIBILITY
		, FREELANCER
		, JOB_GRADE_CODE
		, POSITION_CODE
		, CAREER_YEAR
		, SALARY
		, LOCATION
		, COM_ID
	) VALUES (
		#{careerNo}
		, #{resumeNo}
		, #{jobCode}
		, REPLACE(#{startWorkDate}, '-', '')
		, REPLACE(#{retireDate}, '-', '')
		, #{tenure}
		, #{department}
		, #{responsibility}
		, #{freelancer}
		, #{jobGradeCode}
		, #{positionCode}
		, #{careerYear}
		, #{salary}
		, #{location}
		, #{comId}
	)

mapper.update:
UPDATE CAREER 
   SET RESUME_NO = #{resumeNo}
   	   , JOB_CODE = #{jobCode}
   	   , START_WORK_DATE = REPLACE(#{startWorkDate}, '-', '')
   	   , RETIRE_DATE = REPLACE(#{retireDate}, '-', '')
   	   , TENURE = #{tenure}
   	   , DEPARTMENT = #{department}
   	   , RESPONSIBILITY = #{responsibility}
   	   , FREELANCER = #{freelancer}
   	   , JOB_GRADE_CODE = #{jobGradeCode}
   	   , POSITION_CODE = #{positionCode}
   	   , CAREER_YEAR = #{careerYear}
   	   , SALARY = #{salary}
   	   , LOCATION = #{location} 
   	   , COM_ID = #{comId}
 WHERE CAREER_NO = #{careerNo}

	UPDATE CAREER 
  SET DELETE_DATE = SYSDATE
 	WHERE CAREER_NO = #{careerNo}
  AND RESUME_NO = #{resumeNo}
